var translationPattern=new RegExp('(?<![\\p{L}\\p{N}])(?:'+Object.keys(translations)
  .sort(function(a,b){return b.length-a.length;})
  .map(function(key){return key.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}).join('|')+')(?![\\p{L}\\p{N}])','gu');
function tr(text){return english?text.replace(translationPattern,function(key){return translations[key];}):text;}
// Keep the original labels so the same DOM can switch back to Bahasa Melayu.
var originalText=new WeakMap(), originalAttributes=new WeakMap();
function localise(root){
  var walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT), node;
  while((node=walker.nextNode())){
    if(node.parentElement.closest('script,style,textarea,#pr-main,#pr-ideas,#pr-share,[data-user-text]'))continue;
    if(!originalText.has(node))originalText.set(node,node.nodeValue);
    node.nodeValue=tr(originalText.get(node));
  }
  root.querySelectorAll('[placeholder],[aria-label],[alt]').forEach(function(element){
    if(!originalAttributes.has(element))originalAttributes.set(element,{});
    var original=originalAttributes.get(element);
    ['placeholder','aria-label','alt'].forEach(function(attr){
      if(!element.hasAttribute(attr))return;
      if(!(attr in original))original[attr]=element.getAttribute(attr);
      element.setAttribute(attr,tr(original[attr]));
    });
  });
}
function renderLanguage(){
  document.documentElement.lang=english?'en':'ms';
  document.querySelectorAll('[data-lang]').forEach(function(button){
    button.setAttribute('aria-pressed',button.dataset.lang===(english?'en':'ms'));
  });
  localise(document.body);
  moRender();
  document.getElementById('agenda').innerHTML=SES.map(function(session,i){
    return '<li>'+topicLink(ROUTES[i],session.t+'–'+session.e+' · '+TITLES[i],false)+'</li>';
  }).join('');
  var expanded=Array.from(document.querySelectorAll('#panel details'),function(detail){return detail.open;});
  route(false);
  document.querySelectorAll('#panel details').forEach(function(detail,i){detail.open=Boolean(expanded[i]);});
  if(document.getElementById('help').open)faq();
}
document.querySelectorAll('[data-lang]').forEach(function(button){
  button.addEventListener('click',function(){
    var next=button.dataset.lang==='en';
    if(english===next)return;
    english=next;
    renderLanguage();
    var url=new URL(location.href);
    if(english)url.searchParams.set('lang','en');else url.searchParams.delete('lang');
    try{history.replaceState(history.state,'',url.href);}catch(error){/* The switch also works in local previews. */}
  });
});

