  var prior=Object.assign({},S), previousIndex=prior.cur;
  [7,8,9,10,11,12].forEach(function(i){delete S['done'+i];});
  [9,7,10,11,12].forEach(function(oldIndex,i){if(prior['done'+oldIndex])S['done'+(i+7)]=true;});
