function N(t){return '<div class="note"><img src="'+JULIE+'" alt=""><div><b>Pesanan Madam Julie</b><p>'+t+'</p></div></div>';}
function nm(){return v('name','');}
function shareUrl(){return v('shurl',v('ghurl',v('nlurl','')));}
function F(k,lab,ph,type,fallback){return '<label class="f" for="f-'+k+'">'+lab+'</label><input type="'+(type||'text')+'" id="f-'+k+'" data-k="'+k+'" value="'+esc(S[k]??fallback??'')+'" placeholder="'+esc(ph||'')+'">';}

