   '<div class="gx-right"><article class="gx-box"><h4>✅ '+LX(['Mesti ada','Must have'])+'</h4><ul class="gx-must">'+t.must.map(function(m){return '<li>'+LX(m)+'</li>';}).join('')+'</ul></article>'+
   '<article class="gx-box"><h4>📦 '+LX(['Aset yang perlu disediakan','Assets to prepare'])+'</h4><ul class="gx-assets">'+t.assets.map(function(a){return '<li><span>'+a[0]+'</span><div><b>'+LX(a[1])+'</b><small>'+LX(a[2])+'</small></div></li>';}).join('')+'</ul></article>'+
   '<article class="gx-box"><h4>🎨 '+LX(['Kit reka bentuk','Design kit'])+' · '+LX(s.name)+'</h4><div class="gx-pal">'+s.pal.map(function(p){return '<button type="button" class="gx-sw" data-hex="'+p[0]+'" title="'+LX(['Salin','Copy'])+' '+p[0]+'"><i style="background:'+p[0]+'"></i><b>'+p[0]+'</b><small>'+(english?p[2]:p[1])+'</small></button>';}).join('')+'</div><p class="gx-font"><b>'+LX(['Fon:','Font:'])+'</b> '+s.font+'</p><p class="hint" style="margin:4px 0 0">'+LX(['Tekan warna untuk menyalin kod hex.','Tap a colour to copy its hex code.'])+'</p></article></div></div>'+
   '<h3 class="gx-h">'+LX(['Prompt sedia guna','Ready-to-use prompts'])+'</h3><div class="ax-seg gx-ptabs">'+ps.map(function(p){var on=p===cur;return '<button type="button" class="'+(on?'on':'')+'" data-gxprompt="'+p[0]+'" aria-pressed="'+on+'">'+LX(p[1])+'</button>';}).join('')+'</div>'+
   '<p class="hint">'+LX(cur[2])+'</p><div class="prompt"><header><span>'+LX(cur[1])+' · '+LX(t.name)+' · '+LX(s.name)+'</span><button class="btn sm" type="button" id="gx-copy">'+LX(['Salin','Copy'])+'</button></header><pre id="gx-pre">'+esc(cur[3])+'</pre></div>'+
   '<p class="gx-note">💡 '+LX(['Pilihan jenis dan gaya di sini juga digunakan dalam prompt anda di Studio praktikal.','Your type and style choices here are also used in your prompt in the Practice studio.'])+'</p>';
