function gxRefresh(anim){var b=document.getElementById('gx-body');if(!b)return;b.innerHTML=gxBody();bindGallery();
  if(anim){var site=b.querySelector('.gx-site');if(site){site.classList.add('gx-in');}}}
function bindGallery(){
  var root=document.getElementById('gx');if(!root)return;
  root.querySelectorAll('[data-gxtype]').forEach(function(b){b.onclick=function(){S.type=b.dataset.gxtype;save();gxSync();gxRefresh(true);};});
  root.querySelectorAll('[data-gxstyle]').forEach(function(b){b.onclick=function(){S.style=b.dataset.gxstyle;save();gxSync();gxRefresh(true);};});
  root.querySelectorAll('[data-gxprompt]').forEach(function(b){b.onclick=function(){S.gxPrompt=b.dataset.gxprompt;save();gxRefresh(false);};});
  var l=document.getElementById('gx-labels');if(l)l.onchange=function(){S.gxLabels=l.checked;save();gxRefresh(false);};
  var c=document.getElementById('gx-copy');if(c)c.onclick=function(){copyText(c,document.getElementById('gx-pre').textContent);};
  root.querySelectorAll('[data-hex]').forEach(function(b){b.onclick=function(){var t=b.querySelector('b');copyText(t,b.dataset.hex);};});
}
function gxSync(){
  ['type','style'].forEach(function(k){document.querySelectorAll('#panel [data-pick="'+k+'"]').forEach(function(x){x.setAttribute('aria-pressed',x.dataset.val===S[k]);});});
  var a=document.getElementById('kx-type'),b=document.getElementById('kx-style');if(a)a.textContent=tr(v('type',''));if(b)b.textContent=tr(v('style',''));
  if(typeof refreshPrompts==='function')refreshPrompts();
}
function bindGalleryPicks(){document.querySelectorAll('#panel [data-pick]').forEach(function(b){b.addEventListener('click',function(){setTimeout(function(){gxRefresh(true);},0);});});}

