var AX_TABS=[['parts','Bahagian laman web'],['layers','Tiga lapisan kod'],['journey','Dari fail ke skrin'],['terms','Istilah asas']];
var AX_LAYERS=[
 {id:'html',n:'HTML',role:'Struktur',an:'Seperti rangka dan dinding rumah.',d:'HTML menentukan apa yang ada pada halaman: tajuk, perenggan, gambar dan butang.',code:'<h3>Kelas Web Wizard</h3>\n<p>Bina laman web pertama anda.</p>\n<button>Daftar</button>'},
 {id:'css',n:'CSS',role:'Gaya',an:'Seperti cat, lantai dan perabot.',d:'CSS menentukan rupa halaman: warna, fon, jarak dan susun atur.',code:'.kad{background:#fff9ef;border:3px solid #10183b;}\nbutton{background:#ffdf35;border-radius:999px;}'},
 {id:'js',n:'JavaScript',role:'Interaksi',an:'Seperti suis lampu dan loceng pintu.',d:'JavaScript membuat halaman bertindak balas apabila pelawat menekan, menaip atau menatal.',code:'button.onclick = () => {\n  mesej.textContent = "Terima kasih!";\n};'}
];
var AX_STEPS=[
 {n:'Fail index.html',i:'📄',d:'Anda tulis kandungan dalam fail index.html. Fail ini mengandungi HTML, CSS dan JavaScript.'},
 {n:'Hos (hosting)',i:'🗄️',d:'Fail dimuat naik ke hos seperti GitHub Pages atau Netlify. Hos ialah komputer yang sentiasa dalam talian.'},
 {n:'Alamat URL',i:'🔗',d:'Hos memberi alamat unik (URL). Sesiapa yang ada pautan ini boleh membuka laman anda.'},
 {n:'Pelayar web',i:'🖥️',d:'Pelawat menekan pautan. Pelayar meminta fail daripada hos, kemudian memaparkan halaman di skrin.'}
];
var AX_TERMS=[
 ['🌐','Laman web','Kumpulan halaman yang boleh dibuka melalui internet menggunakan satu alamat.'],
 ['🔗','URL','Alamat penuh sesebuah halaman, contohnya https://nama.netlify.app.'],
 ['🏷️','Domain','Nama yang mudah diingat dalam alamat, contohnya polipd.edu.my.'],
 ['🗄️','Hos (hosting)','Perkhidmatan yang menyimpan fail laman web supaya boleh dibuka pada bila-bila masa.'],
 ['🖥️','Pelayar web','Aplikasi untuk membuka laman web, contohnya Chrome, Safari atau Edge.'],
 ['📱','Responsif','Laman web menyusun semula kandungan supaya kemas di telefon, tablet dan komputer.'],
 ['🧭','Navigasi','Menu dan pautan yang membantu pelawat berpindah antara bahagian.'],
 ['🔒','HTTPS','Ikon mangga pada pelayar. Menunjukkan sambungan ke laman web adalah selamat.']
];
var axTimer=null;
function axStop(){if(axTimer){clearInterval(axTimer);axTimer=null;}}
function anatomy(){
  return '<section class="ax" id="ax"><p class="mono2 ax-kick">Rajah interaktif</p><h2>Bagaimana laman web berfungsi?</h2><p>Terokai empat bahagian ini untuk memahami asas sebuah laman web sebelum anda membina laman sendiri.</p>'+
   '<div class="ax-tabs" role="tablist" aria-label="Topik rajah">'+AX_TABS.map(function(t,i){var on=(S.axTab||'parts')===t[0];return '<button type="button" role="tab" class="ax-tab'+(on?' on':'')+'" data-axtab="'+t[0]+'" aria-selected="'+on+'"><em>0'+(i+1)+'</em>'+t[1]+'</button>';}).join('')+'</div>'+
   '<div class="ax-book"><div class="ax-page" id="ax-page">'+axPage()+'</div></div></section>';
}
function axPage(){
  var t=S.axTab||'parts';
  if(t==='layers')return axLayers();
  if(t==='journey')return axJourney();
  if(t==='terms')return axTerms();
  return axParts();
}
function axParts(){
  var on=S.anat||'header',view=S.anatView||'desk';
  var b=function(id,inner){var x=ANAT.find(function(a){return a.id===id;}),n=ANAT.indexOf(x)+1;
    return '<button type="button" class="wf-part wf-'+id+' c-'+x.c+(on===id?' on':'')+'" data-part="'+id+'" aria-pressed="'+(on===id)+'"><span class="wf-call c-'+x.c+'"><b>0'+n+'</b>'+x.n+'</span>'+inner+'</button>';};
  var bars=function(n,w){var h='';for(var i=0;i<n;i++)h+='<i style="width:'+(w[i]||70)+'%"></i>';return '<span class="wf-lines">'+h+'</span>';};
  var wire='<div class="wf-browser wf-'+view+'"><div class="wf-bar"><span></span><span></span><span></span><em>🔒 https://laman-saya.netlify.app</em></div><div class="wf-page" id="wf-page">'+
    b('header','<span class="wf-logo"></span><span class="wf-menu"><i></i><i></i><i></i></span>')+
    b('hero','<span class="wf-hero-txt"><b class="wf-h1"></b>'+bars(2,[80,60])+'<span class="wf-btn"></span></span><span class="wf-img"></span>')+
    b('content','<span class="wf-cards"><span>'+bars(3,[60,90,70])+'</span><span>'+bars(3,[60,90,70])+'</span><span>'+bars(3,[60,90,70])+'</span></span>')+
    b('proof','<span class="wf-gal"><span class="wf-img"></span><span class="wf-img"></span><span class="wf-img"></span><span class="wf-img"></span></span>')+
    b('cta','<span class="wf-cta-txt">'+bars(1,[55])+'</span><span class="wf-btn"></span>')+
    b('footer',bars(2,[40,30]))+
    '<span class="wf-scroll" aria-hidden="true"><i id="wf-thumb"></i></span></div></div>';
  return '<div class="ax-tools"><div class="ax-seg" role="group" aria-label="Paparan peranti"><button type="button" class="'+(view==='desk'?'on':'')+'" data-view="desk" aria-pressed="'+(view==='desk')+'">🖥 Desktop</button><button type="button" class="'+(view==='mob'?'on':'')+'" data-view="mob" aria-pressed="'+(view==='mob')+'">📱 Telefon</button></div>'+
    '<button type="button" class="btn sm" id="ax-tour" aria-pressed="'+Boolean(axTimer)+'">'+(axTimer?'⏸ Hentikan lawatan':'▶ Lawatan berpandu')+'</button></div>'+
   '<p class="ax-key"><b>Cara membacanya:</b> Header <u>memperkenalkan</u> → Hero <u>menarik perhatian</u> → Kandungan <u>menerangkan</u> → Bukti <u>meyakinkan</u> → CTA <u>mengajak</u> → Footer <u>menyokong</u>.</p>'+
   '<div class="wf-wrap">'+wire+'<div class="wf-side"><article class="wf-info" id="wf-info" aria-live="polite">'+anatInfo(on)+'</article>'+
   '<div class="ax-step"><button type="button" class="btn sm" data-step="-1" aria-label="Bahagian sebelum">← Sebelum</button><span id="ax-count" class="mono2">'+axCount(on)+'</span><button type="button" class="btn sm blue" data-step="1" aria-label="Bahagian seterusnya">Seterusnya →</button></div></div></div>'+
   '<p class="hint">'+(view==='mob'?'Di telefon, bahagian yang sama disusun secara menegak dan menu biasanya dilipat menjadi ikon ☰.':'Di desktop, kandungan boleh disusun bersebelahan kerana skrin lebih lebar.')+'</p>';
}
function axCount(id){var i=ANAT.findIndex(function(a){return a.id===id;});return '0'+(i+1)+' / 0'+ANAT.length;}
function anatInfo(id){var x=ANAT.find(function(a){return a.id===id;})||ANAT[0];
  return tr('<header class="c-'+x.c+'"><b>'+axCount(x.id)+'</b><h3>'+x.n+'</h3><span class="ax-verb">'+x.k+'</span></header><dl>'+
   '<dt>Apa</dt><dd>'+x.what+'</dd><dt>Cara</dt><dd>'+x.how+'</dd><dt>Fungsi</dt><dd>'+x.f+'</dd><dt>Ciri</dt><dd>'+x.has+'</dd><dt>Tag HTML</dt><dd><code>'+esc(x.tag)+'</code></dd></dl><p class="ax-tip">💡 '+x.tip+'</p>');}
function axLayers(){
  var l=S.layer||'html',lv=['html','css','js'].indexOf(l),x=AX_LAYERS[lv];
  return '<p>Setiap laman web dibina dengan tiga lapisan kod. Tekan setiap lapisan dan lihat bagaimana contoh di bawah berubah.</p>'+
   '<div class="ax-seg ax-layers" role="group" aria-label="Lapisan kod">'+AX_LAYERS.map(function(a,i){return '<button type="button" class="'+(i<=lv?'on':'')+'" data-layer="'+a.id+'" aria-pressed="'+(a.id===l)+'">'+(i?'+ ':'')+a.n+'</button>';}).join('')+'</div>'+
   '<div class="ax-lab"><div class="ax-demo lv'+lv+'"><div class="ax-demo-card"><h3>Kelas Web Wizard</h3><p>Bina laman web pertama anda.</p><button type="button" id="ax-demo-btn">Daftar</button><p class="ax-msg" id="ax-msg" aria-live="polite"></p></div>'+
   '<small class="mono2">'+(lv===0?'Hanya HTML: kandungan ada, tetapi tiada gaya.':lv===1?'HTML + CSS: kemas dan menarik, tetapi butang belum berfungsi.':'HTML + CSS + JavaScript: cuba tekan butang Daftar.')+'</small></div>'+
   '<article class="ax-layer-info"><header><b>'+x.n+'</b><span>'+x.role+'</span></header><p class="ax-an">🏠 '+x.an+'</p><p>'+x.d+'</p><pre><code>'+esc(x.code)+'</code></pre></article></div>';
}
function axJourney(){
  var s=S.jstep==null?-1:S.jstep;
  return '<p>Apabila seseorang membuka pautan laman web anda, empat perkara ini berlaku dalam masa sesaat dua.</p>'+
   '<div class="ax-tools"><button type="button" class="btn sm blue" id="ax-play">▶ Mainkan animasi</button><button type="button" class="btn sm" id="ax-reset">↺ Mula semula</button></div>'+
   '<div class="ax-flow"><span class="ax-line"><i id="ax-packet" style="left:'+(s<0?0:s*33.333)+'%"></i></span>'+
   AX_STEPS.map(function(x,i){return '<button type="button" class="ax-node'+(i<=s?' lit':'')+(i===s?' now':'')+'" data-jstep="'+i+'"><span class="ax-ic">'+x.i+'</span><em>0'+(i+1)+'</em><b>'+x.n+'</b></button>';}).join('')+'</div>'+
   '<p class="ax-cap" id="ax-cap" aria-live="polite">'+(s<0?'Tekan Mainkan animasi atau pilih mana-mana langkah.':'<b>0'+(s+1)+' '+AX_STEPS[s].n+'.</b> '+AX_STEPS[s].d)+'</p>';
}
function axTerms(){
  return '<p>Istilah yang akan anda dengar sepanjang bengkel. Tekan kad untuk melihat maksudnya.</p><div class="ax-terms">'+
   AX_TERMS.map(function(t,i){return '<button type="button" class="ax-card" data-card="'+i+'" aria-pressed="false"><span class="ax-face ax-front"><span class="ax-ic">'+t[0]+'</span><b>'+t[1]+'</b><small>Tekan untuk lihat maksud</small></span><span class="ax-face ax-back"><b>'+t[1]+'</b><span>'+t[2]+'</span></span></button>';}).join('')+'</div>';
}
function axRefresh(anim){
  var p=document.getElementById('ax-page');if(!p)return axStop();
  p.innerHTML=axPage();localise(p);bindAnatomy();
  if(anim){p.classList.remove('turn');void p.offsetWidth;p.classList.add('turn');}
  axThumb();
}
function axThumb(){var page=document.getElementById('wf-page'),th=document.getElementById('wf-thumb'),on=document.querySelector('#ax .wf-part.on');
  if(!page||!th||!on)return;th.style.top=(on.offsetTop/page.scrollHeight*100)+'%';th.style.height=Math.max(10,on.offsetHeight/page.scrollHeight*100)+'%';}
function axPick(id){
  S.anat=id;save();
  document.querySelectorAll('#ax [data-part]').forEach(function(x){var o=x.dataset.part===id;x.classList.toggle('on',o);x.setAttribute('aria-pressed',o);});
  var info=document.getElementById('wf-info');info.innerHTML=anatInfo(id);info.classList.remove('flip');void info.offsetWidth;info.classList.add('flip');
  document.getElementById('ax-count').textContent=axCount(id);axThumb();
}
function axMove(d){var i=ANAT.findIndex(function(a){return a.id===(S.anat||'header');});axPick(ANAT[(i+d+ANAT.length)%ANAT.length].id);}
function bindAnatomy(){
  var root=document.getElementById('ax');if(!root)return axStop();
  root.querySelectorAll('[data-axtab]').forEach(function(btn){btn.onclick=function(){axStop();S.axTab=btn.dataset.axtab;save();
    root.querySelectorAll('[data-axtab]').forEach(function(x){var o=x===btn;x.classList.toggle('on',o);x.setAttribute('aria-selected',o);});axRefresh(true);};});
  root.querySelectorAll('[data-part]').forEach(function(btn){btn.onclick=function(){axStop();axPick(btn.dataset.part);var t=document.getElementById('ax-tour');if(t)t.textContent=tr('▶ Lawatan berpandu');};});
  root.querySelectorAll('[data-step]').forEach(function(btn){btn.onclick=function(){axMove(+btn.dataset.step);};});
  root.querySelectorAll('[data-view]').forEach(function(btn){btn.onclick=function(){S.anatView=btn.dataset.view;save();axRefresh(false);};});
  var tour=document.getElementById('ax-tour');
  if(tour)tour.onclick=function(){if(axTimer){axStop();tour.textContent=tr('▶ Lawatan berpandu');return;}
    axPick('header');tour.textContent=tr('⏸ Hentikan lawatan');
    axTimer=setInterval(function(){if(!document.getElementById('wf-info'))return axStop();
      if((S.anat||'header')==='footer'){axStop();var t=document.getElementById('ax-tour');if(t)t.textContent=tr('▶ Lawatan berpandu');return;}axMove(1);},3200);};
  root.querySelectorAll('[data-layer]').forEach(function(btn){btn.onclick=function(){S.layer=btn.dataset.layer;save();axRefresh(false);};});
  var demo=document.getElementById('ax-demo-btn');
  if(demo)demo.onclick=function(){var m=document.getElementById('ax-msg');
    m.textContent=(S.layer||'html')==='js'?tr('Terima kasih! Pendaftaran anda diterima. 🎉'):tr('Tiada apa berlaku. Butang perlukan JavaScript untuk berfungsi.');};
  var jumpTo=function(i){S.jstep=i;save();var cap=document.getElementById('ax-cap'),pk=document.getElementById('ax-packet');
    root.querySelectorAll('[data-jstep]').forEach(function(n,k){n.classList.toggle('lit',k<=i);n.classList.toggle('now',k===i);});
    if(pk)pk.style.left=(i<0?0:i*33.333)+'%';
    if(cap)cap.innerHTML=i<0?tr('Tekan Mainkan animasi atau pilih mana-mana langkah.'):tr('<b>0'+(i+1)+' '+AX_STEPS[i].n+'.</b> '+AX_STEPS[i].d);};
  root.querySelectorAll('[data-jstep]').forEach(function(n){n.onclick=function(){axStop();jumpTo(+n.dataset.jstep);};});
  var play=document.getElementById('ax-play');
  if(play)play.onclick=function(){axStop();var i=0;jumpTo(0);axTimer=setInterval(function(){if(!document.getElementById('ax-cap'))return axStop();i++;if(i>=AX_STEPS.length)return axStop();jumpTo(i);},2600);};
  var rs=document.getElementById('ax-reset');if(rs)rs.onclick=function(){axStop();jumpTo(-1);};
  root.querySelectorAll('[data-card]').forEach(function(c){c.onclick=function(){var o=!c.classList.contains('flipped');c.classList.toggle('flipped',o);c.setAttribute('aria-pressed',o);};});
  requestAnimationFrame(axThumb);
}

function publishingOverview(){
  return '<h2>Mulakan dengan satu projek yang lengkap</h2>'+
    '<p>Untuk bengkel ini, sediakan satu fail utama <code>index.html</code>. HTML menyusun kandungan, CSS menentukan rupa dan JavaScript menambah interaksi jika diperlukan. CSS dan JavaScript boleh berada dalam fail HTML yang sama atau dalam fail berasingan.</p>'+
    '<p>Sertakan aset yang digunakan, seperti gambar, ikon atau fon. Jika aset disimpan dalam projek, gunakan laluan relatif seperti <code>assets/logo.webp</code> dan kekalkan struktur folder ketika memuat naik. Buka <code>index.html</code> dalam pelayar untuk menguji kandungan dan pautan.</p>'+
    '<h2>Terbit atau kongsi terus daripada alat AI</h2>'+
    '<details class="guide"><summary>ChatGPT · Sites</summary><div><p>Bina laman melalui Sites, semak pratonton dan terbitkan menggunakan pilihan akses yang tersedia. Jika pilihan akses awam dibenarkan untuk akaun atau ruang kerja anda, kongsi URL laman yang diterbitkan.</p><a href="https://help.openai.com/en/articles/20001339-creating-and-using-chatgpt-sites" target="_blank" rel="noopener">Panduan ChatGPT Sites ↗</a></div></details>'+
    '<details class="guide"><summary>Gemini · Canvas</summary><div><p>Buka aplikasi atau laman yang dibina dalam Canvas, pilih <b>Share</b> dan salin pautan jika pilihan itu tersedia. Pautan ini membuka projek dalam Gemini di pelayar. Ia sesuai untuk berkongsi demo atau prototaip.</p><a href="https://support.google.com/gemini/answer/16047321" target="_blank" rel="noopener">Panduan Gemini Canvas ↗</a></div></details>'+
    '<details class="guide"><summary>Claude · Artifacts</summary><div><p>Buka Artifact dan gunakan <b>Share</b> atau <b>Publish</b>, mengikut jenis Artifact, pelan dan tetapan organisasi. Semak siapa yang boleh membuka pautan dan sama ada ciri tertentu memerlukan akaun Claude.</p><a href="https://support.claude.com/en/articles/9547008-share-artifacts" target="_blank" rel="noopener">Panduan Claude Artifacts ↗</a></div></details>'+
    '<h2>Bila GitHub Pages atau Netlify lebih sesuai?</h2>'+
    '<p>Kedua-duanya menerima fail laman statik daripada mana-mana alat AI. Anda boleh simpan salinan lengkap, ubah fail kemudian dan pindahkan projek ke hos lain. Kedua-duanya juga menyokong domain sendiri, tertakluk pada tetapan hos dan domain.</p>'+
    '<div class="grid2"><article class="chip"><h3>GitHub Pages · Projek yang kerap dikemas kini</h3><p>Fail dan sejarah perubahan berada dalam repositori. Sesuai untuk portfolio, dokumentasi dan bahan kursus yang mahu diselenggara dari semasa ke semasa.</p><a href="#github">Buka panduan GitHub Pages →</a></article>'+
    '<article class="chip"><h3>Netlify · Terbit daripada folder projek</h3><p>Gunakan Netlify Drop untuk memuat naik folder tanpa menyediakan repositori dahulu. Sambungkan repositori Git kemudian jika anda mahu penerbitan automatik.</p><a href="#netlify">Buka panduan Netlify →</a></article></div>'+
    '<p class="hint">Jika laman bergantung pada log masuk, pangkalan data atau AI terbina dalam, semak keperluan perkhidmatan tersebut sebelum memindahkannya ke hos statik.</p>';
}
function platformGuide(index,steps){
  var github=index===7;
  var terms=github?[
    ['Repository','Folder projek dalam GitHub. Di sinilah fail laman disimpan.'],
    ['Commit changes','Simpan perubahan fail ke dalam sejarah projek.'],
    ['Settings → Pages','Ruang untuk mengaktifkan penerbitan dan mendapatkan URL awam.'],
    ['Branch dan /(root)','Pilih versi projek dan direktori utama yang mengandungi index.html.']
  ]:[
    ['Netlify Drop','Ruang muat naik manual untuk folder laman.'],
    ['Project','Ruang pengurusan laman anda selepas diterbitkan.'],
    ['Deploys','Sejarah versi laman. Gunakan ruang ini untuk memuat naik versi baharu.'],
    ['URL awam','Pautan netlify.app yang boleh dibuka oleh pelawat.']
  ];
  return '<p>'+(github?'GitHub Pages menerbitkan laman daripada repositori GitHub. Pilih laluan ini jika anda mahu belajar menyimpan dan mengemas kini fail projek dalam GitHub.':'Netlify Drop menerbitkan folder laman terus daripada komputer. Pilih laluan ini jika anda mahu cuba muat naik folder secara manual.')+'</p>'+
    '<details class="guide"><summary>Kenali label dan ruang kerja '+TITLES[index]+'</summary><div><dl class="platform-map">'+terms.map(function(term){return '<dt>'+term[0]+'</dt><dd>'+term[1]+'</dd>';}).join('')+'</dl></div></details>'+
    '<details class="guide"><summary>Buka panduan penerbitan dan simpan URL</summary><div>'+steps+'</div></details>';
}
function topicLink(route,label,active){
  return '<a href="#'+route+'"'+(active?' aria-current="page"':'')+'>'+tr(label)+'</a>';
}
function show(i){
  axStop();cur=i;
  var group=SECTIONS.find(function(item){return item.routes.includes(ROUTES[i]);});
  var session=SES[i], body=session?session.body():publishingOverview();
  if(i===2)body=kenali(body);
  if(i===7||i===8)body=platformGuide(i,body);
  document.getElementById('section-kicker').textContent=tr(group.label);
  document.getElementById('section-title').textContent=tr(group.name);
  document.getElementById('section-desc').textContent=tr(group.desc);
  sectionArt(group.routes[0]);
  document.getElementById('rail').innerHTML=group.routes.map(function(route){
    var index=ROUTES.indexOf(route);
    return topicLink(route,TITLES[index],index===cur);
  }).join('');
  document.getElementById('panel').innerHTML='<header class="ph">'+(session?'<span class="lab">'+session.t.replace(':','.')+'–'+session.e.replace(':','.')+'</span>':'')+'<h2>'+TITLES[i]+'</h2>'+(session?'<p class="goal">'+session.goal+'</p>':'')+'</header>'+
    '<div class="pb">'+body+'</div>'+(session?'<div class="pf"><label class="done"><input type="checkbox" id="doneBox"'+(S['done'+i]?' checked':'')+'> Tandakan selesai</label></div>':'');
  localise(document.getElementById('panel'));
  refreshPrompts();
  bind();
}
var currentRoute=(location.hash||'').slice(1);
function go(r){currentRoute=r;try{if(location.hash!=='#'+r)history.pushState(null,'','#'+r);}catch(e){}route(true);}
function route(focus){
  var current=currentRoute, index=ROUTES.indexOf(current);
  var group=SECTIONS.find(function(item){return item.routes.includes(current);});
  document.getElementById('home').hidden=index>=0;
  document.getElementById('workspace').hidden=index<0;
  document.querySelectorAll('#site-nav a').forEach(function(link){
    var selected=link.hash==='#'+(group?group.routes[0]:'utama');
    if(selected)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');
  });
  if(index>=0)show(index);
  if(focus){window.scrollTo(0,0);if(index>=0)document.getElementById('section-title').focus();}
}

function refreshPrompts(){var m=document.getElementById('pr-main');if(m)m.textContent=mainPrompt();
  var sh=document.getElementById('pr-share');if(sh)sh.textContent=v('shname',tr('[Nama laman]'))+' | '+(shareUrl()||'[URL]')+' | '+v('shwhat',tr('[Satu perkara yang saya bina atau baiki]'));
  var id=document.getElementById('pr-ideas');if(id)id.textContent=english?'I want to build a '+tr(v('type','Profil atau portfolio'))+' website for '+v('aud','[audience]')+'. Suggest three titles, a two-sentence introduction and three key sections. Use clear English.':'Saya ingin bina laman '+v('type','profil')+' untuk '+v('aud','[audiens]')+'. Cadangkan 3 tajuk menarik, satu penerangan ringkas (2 ayat) dan 3 perkara utama yang patut ada. Gunakan Bahasa Melayu yang mudah.';}

function copyText(btn,t){function ok(){var o=btn.textContent;btn.textContent=tr('✓ Disalin');setTimeout(function(){btn.textContent=o},1500);}
  if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(t).then(ok,fb);else fb();
  function fb(){var ta=document.createElement('textarea');ta.value=t;document.body.appendChild(ta);ta.select();try{document.execCommand('copy');ok();}catch(e){}ta.remove();}}

function bind(){
  document.querySelectorAll('#panel [data-k]').forEach(function(el){var k=el.dataset.k;el.addEventListener(el.type==='checkbox'?'change':'input',function(){S[k]=el.type==='checkbox'?el.checked:el.value;save();refreshPrompts();});});
  document.querySelectorAll('#panel [data-copy]').forEach(function(b){b.addEventListener('click',function(){var el=document.getElementById(b.dataset.copy);copyText(b,el.tagName==='PRE'?el.textContent:el.value);});});
  document.querySelectorAll('#panel [data-pick]').forEach(function(b){b.addEventListener('click',function(){S[b.dataset.pick]=b.dataset.val;save();document.querySelectorAll('[data-pick="'+b.dataset.pick+'"]').forEach(function(x){x.setAttribute('aria-pressed',x===b);});});});
  document.querySelectorAll('#panel .tabs button').forEach(function(b){b.addEventListener('click',function(){document.querySelectorAll('#panel .tabs button').forEach(function(x){x.setAttribute('aria-selected',x===b);document.getElementById('pane-'+x.dataset.pane).hidden=x!==b;});});});
  var dl=document.getElementById('dl');if(dl)dl.addEventListener('click',download);
  var oh=document.querySelector('[data-open-help]');if(oh)oh.addEventListener('click',openHelp);
  document.querySelectorAll('#panel form.survey').forEach(bindSurvey);
  bindAnatomy();bindGallery();bindKenali();
  var doneBox=document.getElementById('doneBox');
  if(doneBox)doneBox.onchange=function(e){S['done'+cur]=e.target.checked;save();};
}

