var KX=[['faham','Faham cara laman web berfungsi','compass'],['contoh','Contoh, aset dan prompt','layout'],['pilih','Inspirasi dan pilihan anda','palette']];
function kenali(body){
  var k=S.kTab||'faham';
  return '<nav class="kx-steps" aria-label="Langkah Kenali laman web">'+KX.map(function(x,i){var on=x[0]===k;return '<button type="button" class="kx-step'+(on?' on':'')+'" data-kx="'+x[0]+'" aria-pressed="'+on+'"><span class="kx-ic">'+IC(x[2])+'</span><span><small class="mono2">Langkah '+(i+1)+'</small><b>'+x[1]+'</b></span></button>';}).join('')+'</nav>'+
   '<div class="kx-pane" data-kxpane="faham"'+(k==='faham'?'':' hidden')+'>'+anatomy()+kxNext(1)+'</div>'+
   '<div class="kx-pane" data-kxpane="contoh"'+(k==='contoh'?'':' hidden')+'>'+examples()+kxNext(2)+'</div>'+
   '<div class="kx-pane" data-kxpane="pilih"'+(k==='pilih'?'':' hidden')+'>'+designInspiration()+body+'</div>';
}
