function IC(n,c){return '<svg class="ic'+(c?' '+c:'')+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+(ICP[n]||ICP.sparkle)+'</svg>';}
var EMOJI_IC=[['👩‍🏫','user'],['🧑‍🏫','user'],['💡','bulb'],['🤖','bot'],['🔗','link'],['☕','coffee'],['📱','phone'],['🎨','palette'],['➕','plus'],['💛','help'],['✅','check'],['✉','mail'],['📄','file'],['🗄','server'],['🖥','monitor'],['🌐','globe'],['🏷','tag'],['🧭','compass'],['🔒','lock'],['📅','calendar'],['📚','book'],['📘','book'],['🛍','bag'],['🖼','image'],['🗂','folder'],['✍','pen'],['📝','clipboard'],['🏛','building'],['▶','play'],['⏸','pause'],['↺','reset'],['💲','dollar'],['📞','message'],['📸','camera'],['🎧','headphones'],['🗣','mic'],['🏆','trophy'],['📦','package'],['⏰','clock'],['📍','pin'],['🏠','home'],['🎉','sparkle'],['☰','menu'],['🎬','video']];
var EMOJI_RE=new RegExp('('+EMOJI_IC.map(function(e){return e[0];}).join('|')+')️?','gu');
var EMOJI_MAP={};EMOJI_IC.forEach(function(e){EMOJI_MAP[e[0]]=e[1];});
function iconise(root){
  if(!root||root.nodeType===3&&!(root=root.parentNode))return;
  if(root.nodeType!==1)return;
  var w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),n,list=[];
  while((n=w.nextNode())){if(EMOJI_RE.test(n.nodeValue)&&!n.parentElement.closest('pre,textarea,script,style,option,title,[data-noicon]'))list.push(n);EMOJI_RE.lastIndex=0;}
  list.forEach(function(t){
    var span=document.createElement('span');span.className='ic-wrap';
    span.innerHTML=esc(t.nodeValue).replace(EMOJI_RE,function(m,e){return IC(EMOJI_MAP[e]);});
    var f=document.createDocumentFragment();while(span.firstChild)f.appendChild(span.firstChild);
    t.parentNode.replaceChild(f,t);
  });
}
(function(){
  var go=function(){iconise(document.body);
    new MutationObserver(function(ms){ms.forEach(function(m){if(m.type==='characterData')iconise(m.target.parentNode);else m.addedNodes.forEach(function(x){iconise(x.nodeType===3?x.parentNode:x);});});})
      .observe(document.body,{childList:true,subtree:true,characterData:true});
    var NAV={utama:'home',persediaan:'clipboard',kenali:'compass',praktikal:'wand',terbit:'rocket',kongsi:'message'};
    document.querySelectorAll('#site-nav a').forEach(function(a){var k=(a.getAttribute('href')||'').slice(1);if(NAV[k]&&!a.querySelector('.ic'))a.insertAdjacentHTML('afterbegin',IC(NAV[k],'nav-ic'));});
  };
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',go);else go();
})();

