var SEC_IC={persediaan:'clipboard',kenali:'compass',praktikal:'wand',terbit:'rocket',kongsi:'message'};
function sectionArt(slug){
  var fig=document.getElementById('wi-art'),img=document.getElementById('section-art'),badge=document.getElementById('wi-badge');
  if(badge){badge.innerHTML=IC(SEC_IC[slug]||'sparkle');var bi=new Image();bi.alt='';bi.onload=function(){badge.innerHTML='';badge.appendChild(bi);badge.classList.add('has-img');};bi.onerror=function(){badge.classList.remove('has-img');};bi.src='./assets/icon-'+slug+'.png';}
  if(!fig||!img)return;
  fig.hidden=true;document.querySelector('.workspace-intro').classList.remove('has-art');
  img.onload=function(){fig.hidden=false;document.querySelector('.workspace-intro').classList.add('has-art');};
  img.onerror=function(){fig.hidden=true;};
  img.src='./assets/hero-'+slug+'.webp';
}

